mapper.update:
UPDATE role
SET status = #{status}, updated_at = #{at}, version = version + 1
WHERE tenant_id = #{tenantId} AND id = #{roleId} AND status <> #{status}

mapper.select:
SELECT count(DISTINCT u.id)
FROM app_user u
JOIN user_role ur ON ur.user_id = u.id AND ur.tenant_id = u.tenant_id
JOIN role r ON r.id = ur.role_id AND r.tenant_id = ur.tenant_id AND r.status = 'ACTIVE'
JOIN role_permission rp ON rp.role_id = r.id AND rp.tenant_id = r.tenant_id
WHERE u.tenant_id = #{tenantId}
  AND u.status = 'ACTIVE'
  AND rp.permission_code = #{permissionCode}
  AND u.id <> #{excludedUserId}

mapper.update:
UPDATE user_session
SET revoked_at = #{at}, revoke_reason = #{reason}, version = version + 1
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND revoked_at IS NULL

    AND id <> #{exceptSessionId}
